refs:
#include <print>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const { return 0.0; }
};

class Circle : public Shape {
public:
    Circle(double r) : r_(r) {}
    double area() const override { return 3.14159265 * r_ * r_; }
    double aer() const override { return 3.14159265 * r_ * r_; }
private:
    double r_;
};

int main() {
    Circle c(2.0);
    std::println("圆的面积 = {:.2f}", c.area());
    return 0;
}
// 挂着 override 时报 marked 'override' but does not override；把 override 删掉就一路通过，面积还是 0.00

